320	/// Replaces `entry`'s props and `composes` with the checker's, keeping a description or tags only the structural pass
321	/// has, for the whole-project merge. Facts are read as [`merge_semantic_props`] reads them, from `syntax` and as
322	/// `resolver` allows.
323	fn apply_props(
324	    entry: &mut ComponentEntry,
325	    semantic: &SemanticComponent,
326	    shared: &mut FxHashMap<u64, Vec<Arc<ParsedProp>>>,
327	    memo: &mut MergeMemo,
328	    syntax: &SourceSyntax,
329	    resolver: ResolverFacts,
330	) -> MergedProps {
331	    // The whole-project merge replaces the props and leaves `@types/react`'s to the inheritance layers.
332	    let own = semantic.props.iter().filter(|prop| !prop.react_declared);
333	    let merge = Merge { composes: semantic.composes.as_deref(), unanswered: Unanswered::Drop, syntax, resolver };
334	    replace_props(entry, own, &merge, shared, memo)
335	}
