359	/// How a merge went for one component.
360	#[derive(Debug, Clone, Default, PartialEq)]
361	pub struct MergedProps {
362	    /// Structural props the checker did not return, kept as the structural pass resolved them.
363	    pub kept: usize,
364	    /// Props the checker returned with a type it could not read (an `opaque` part: an import that does not resolve, a
365	    /// conditional type it left open), where the structural pass read the type in full. They keep the structural type,
366	    /// and their `degradedBy` also lists what the checker could not read.
367	    pub unread: usize,
368	    /// A source file the merge could not read for the defaults and union order of the answer.
369	    pub diagnostics: Vec<Diagnostic>,
