372	/// Merges the checker's `props` into `entry` by name: the checker's type, optionality, description, tags, `parent` and
373	/// `declarations` win where both have a prop, and every structural prop the checker did not return stays as the
374	/// structural pass resolved it. `composes` replaces the entry's when the checker decided it, and an undecided one leaves
375	/// the structural `composes` ([`SemanticComponent::composes`]). A prop whose checker
376	/// type holds an `opaque` part, where the structural type holds none, keeps the structural type and adds the checker's
377	/// reasons to its `degradedBy`: the checker's answer there is a placeholder, and the structural one is not confirmed,
378	/// so it is marked. A type the checker only cut at a limit (`truncated`) is still its answer.
379	///
380	/// Two facts the checker does not have come from oxc's syntax, read from the files the answer names: a prop's default
381	/// (the component's code: a destructured parameter's initializer, `defaultProps`; else the checker's `@default` tag)
382	/// and the order of a union's members (the order its declaration writes them in). The structural answer gives them
383	/// where the syntax does not tell ([`ResolverFacts::Used`]).
384	pub fn merge_semantic_props<'a>(
385	    entry: &mut ComponentEntry,
386	    props: impl Iterator<Item = &'a Arc<SemanticProp>>,
387	    composes: Option<&[String]>,
388	    shared: &mut FxHashMap<u64, Vec<Arc<ParsedProp>>>,
389	) -> MergedProps {
390	    let props: Vec<Arc<SemanticProp>> = props.cloned().collect();
391	    let syntax = SourceSyntax::read(std::iter::once((&*entry, props.as_slice())));
392	    let merge = Merge { composes, unanswered: Unanswered::Keep, syntax: &syntax, resolver: ResolverFacts::Used };
393	    let mut merged = replace_props(entry, props.iter(), &merge, shared, &mut MergeMemo::default());
394	    merged.diagnostics = syntax.diagnostics;
395	    merged
396	}
