398	/// The kinds of what the checker could not read in `checker`, when the structural type `structural` read everything:
399	/// then the structural type is kept and marked with them. Empty when the checker's type is its answer.
400	fn unread_by_checker(checker: &PropType, structural: &PropType) -> Vec<&'static str> {
401	    let unread: Vec<&'static str> = checker.degraded_by().into_iter().filter(|kind| *kind != TRUNCATED_KIND).collect();
402	    if unread.is_empty() || structural.degraded_by().iter().any(|kind| *kind != TRUNCATED_KIND) {
403	        return Vec::new();
404	    }
405	    unread
406	}
