424	/// A component the checker answered for, as [`drop_superseded`] reads it.
425	pub(crate) struct Superseding<'a> {
426	    key: &'a str,
427	    /// A structural prop the checker did not return still holds a part the structural pass could not read, which a
428	    /// structural diagnostic naming the component may be about.
429	    structural_left: bool,
430	    /// A prop of the merged answer holds a name the checker could not resolve either.
431	    unresolved: bool,
432	}
433	
434	impl<'a> Superseding<'a> {
435	    /// `key`'s component as `merged` holds it after the checker's props were merged in. `structural_left` says whether a
436	    /// structural prop the checker did not return still holds a part the structural pass could not read.
437	    pub(crate) fn new(key: &'a str, merged: &ComponentEntry, structural_left: bool) -> Self {
438	        let unresolved_kind = OpaqueReason::UnresolvableImport { specifier: String::new() }.kind();
439	        let unresolved = merged.props.values().any(|prop| prop.degraded_by.iter().any(|kind| kind == unresolved_kind));
440	        Self { key, structural_left, unresolved }
441	    }
442	
443	    fn supersedes(&self, superseded: Superseded) -> bool {
444	        match superseded {
445	            Superseded::No => false,
446	            Superseded::Yes => !self.structural_left,
447	            Superseded::UnlessUnresolvedByChecker => !self.structural_left && !self.unresolved,
448	        }
449	    }
450	}
