452	/// Takes the components the checker answered for out of the `affects` of each structural diagnostic its answer
453	/// supersedes ([`DiagnosticCode::superseded_by_checker`]), and drops a diagnostic left affecting no component. A
454	/// diagnostic that affected none (a file's, the run's) is about no component's props and stays. Both merges call it
455	/// before the checker's own diagnostics join `diagnostics`, so it reads only the structural pass's.
456	pub(crate) fn drop_superseded(diagnostics: &mut Vec<Diagnostic>, answered: &[Superseding<'_>]) {
457	    if answered.is_empty() {
458	        return;
459	    }
460	    let by_key: FxHashMap<&str, &Superseding<'_>> = answered.iter().map(|answer| (answer.key, answer)).collect();
461	    diagnostics.retain_mut(|diagnostic| {
462	        if diagnostic.affects.is_empty() {
463	            return true;
464	        }
465	        let superseded = diagnostic.code.superseded_by_checker();
466	        diagnostic.affects.retain(|key| by_key.get(key.as_str()).is_none_or(|answer| !answer.supersedes(superseded)));
467	        !diagnostic.affects.is_empty()
468	    });
469	}
