480	/// How one merge reads what the checker does not answer.
481	struct Merge<'a> {
482	    composes: Option<&'a [String]>,
483	    unanswered: Unanswered,
484	    syntax: &'a SourceSyntax,
485	    resolver: ResolverFacts,
486	}
