488	/// A prop's default: the component's code default for it, else the checker's `@default` (or `@defaultValue`) tag, else
489	/// with [`ResolverFacts::Used`] the structural default. The code wins over the tag, as in react-docgen-typescript.
490	fn default_of(
491	    code: Option<&DefaultValue>,
492	    checker_tags: &BTreeMap<String, String>,
493	    structural: Option<&ParsedProp>,
494	    resolver: ResolverFacts,
495	) -> Option<DefaultValue> {
496	    if let Some(code) = code {
497	        return Some(code.clone());
498	    }
499	    let tag = checker_tags.get("default").or_else(|| checker_tags.get("defaultValue"));
500	    if let Some(tag) = tag {
501	        return Some(DefaultValue { value: tag.trim().to_owned(), computed: false });
502	    }
503	    match resolver {
504	        ResolverFacts::Used => structural.and_then(|structural| structural.default_value.clone()),
505	        ResolverFacts::Off => None,
506	    }
507	}
