509	/// The checker's type with its union members in declared order: the order the declaration writes them in where it
510	/// states every member, else the structural union's order where that placed any member (with
511	/// [`ResolverFacts::Used`]), else the written order of the members the declaration does state. Neither leaves the
512	/// checker's order. A structural order that placed members is kept even where it is the checker's own: the partial
513	/// written order would put the members it does not state last, where they may not have been written.
514	fn declared_order(
515	    checker: PropType,
516	    written: Option<&[WrittenMember]>,
517	    structural: Option<&ParsedProp>,
518	    resolver: ResolverFacts,
519	) -> PropType {
520	    let structural = match resolver {
521	        ResolverFacts::Used => structural,
522	        ResolverFacts::Off => None,
523	    };
524	    // The structural order also reaches the unions nested in members, which the written one does not.
525	    let (ordered, placed) = match structural {
526	        Some(structural) => {
527	            let placed = order::places_any(&checker, &structural.prop_type);
528	            (order::in_declared_order(checker, &structural.prop_type), placed)
529	        }
530	        None => (checker, false),
531	    };
532	    match written.and_then(|written| order::in_written_order(&ordered, written)) {
533	        Some((in_written, Placed::All)) => in_written,
534	        Some((in_written, Placed::Some)) if !placed => in_written,
535	        Some(_) | None => ordered,
536	    }
537	}
