539	fn replace_props<'a>(
540	    entry: &mut ComponentEntry,
541	    props_in: impl Iterator<Item = &'a Arc<SemanticProp>>,
542	    merge: &Merge<'_>,
543	    shared: &mut FxHashMap<u64, Vec<Arc<ParsedProp>>>,
544	    memo: &mut MergeMemo,
545	) -> MergedProps {
546	    let Merge { composes, unanswered, syntax, resolver } = *merge;
547	    let code_defaults = syntax.code_defaults(entry);
548	    // Collected, then built into the map in one pass: a design system's components place thousands of props each, and
549	    // one insert per prop searched the map every time. A name given twice keeps the later prop, as an insert did.
550	    let mut placed: Vec<(String, Arc<ParsedProp>)> = Vec::with_capacity(props_in.size_hint().0);
551	    let mut unread = 0;
552	    for prop in props_in {
553	        let structural = entry.props.get(&prop.name);
554	        let code_default = code_defaults.and_then(|defaults| defaults.get(&prop.name));
555	        // The union a prop with a `parent` writes is found by the prop alone, so it needs no place in the key; one with
556	        // none is looked for in the entry's own file.
557	        let written = prop.parent.is_none().then(|| syntax.written(entry, prop));
558	        let key: MergeKey = (
559	            Arc::as_ptr(prop) as usize,
560	            structural.map_or(0, |s| Arc::as_ptr(s) as usize),
561	            written.flatten().map_or((0, 0), |w| (w.as_ptr() as usize, w.len())),
562	            code_default.map_or(0, |d| std::ptr::from_ref(d) as usize),
563	        );
564	        if let Some(made) = memo.made.get(&key) {
565	            unread += usize::from(made.unread);
566	            placed.push((prop.name.clone(), made.merged.clone()));
567	            continue;
568	        }
569	        let written = written.unwrap_or_else(|| syntax.written(entry, prop));
570	        let description = if prop.description.is_empty() {
571	            structural.map(|s| s.description.clone()).unwrap_or_default()
572	        } else {
573	            prop.description.clone()
574	        };
575	        let tags = if prop.tags.is_empty() {
576	            structural.map(|s| s.tags.clone()).unwrap_or_default()
577	        } else {
578	            prop.tags.clone()
579	        };
580	        let unread_kinds = structural.map(|s| unread_by_checker(&prop.prop_type, &s.prop_type)).unwrap_or_default();
581	        let prop_type = match structural {
582	            Some(structural) if !unread_kinds.is_empty() => structural.prop_type.clone(),
583	            Some(_) | None => declared_order(prop.prop_type.clone(), written, structural.map(|s| &**s), resolver),
584	        };
585	        unread += usize::from(!unread_kinds.is_empty());
586	        let merged = ParsedProp::new(
587	            prop.name.clone(),
588	            prop_type,
589	            prop.required,
590	            default_of(code_default, &prop.tags, structural.map(|s| &**s), resolver),
591	            description,
592	            tags,
593	            prop.parent.clone(),
594	            prop.declarations.clone(),
595	        )
596	        .degraded_also_by(&unread_kinds);
597	        let mut hasher = FxHasher::default();
598	        merged.structural_hash(&mut hasher);
599	        let bucket = shared.entry(hasher.finish()).or_default();
600	        let merged = match bucket.iter().find(|existing| ***existing == merged) {
601	            Some(existing) => existing.clone(),
602	            None => {
603	                let merged = Arc::new(merged);
604	                bucket.push(merged.clone());
605	                merged
606	            }
607	        };
608	        memo.made.insert(
609	            key,
610	            MemoEntry {
611	                _semantic: prop.clone(),
612	                _structural: structural.cloned(),
613	                merged: merged.clone(),
614	                unread: !unread_kinds.is_empty(),
615	            },
616	        );
617	        placed.push((prop.name.clone(), merged));
618	    }
619	    let mut props: BTreeMap<String, Arc<ParsedProp>> = placed.into_iter().collect();
620	    let mut kept = 0;
621	    if unanswered == Unanswered::Keep {
622	        for (name, structural) in &entry.props {
623	            if !props.contains_key(name) {
624	                props.insert(name.clone(), structural.clone());
625	                kept += 1;
626	            }
627	        }
628	    }
629	    entry.props = props;
630	    if let Some(composes) = composes {
631	        entry.composes = composes.to_vec();
632	    }
633	    MergedProps { kept, unread, diagnostics: Vec::new() }
634	}
