/// The prefix of the diagnostic [`without_fallback`] writes per reason; the construct suite's checker lane reads the
/// reason after it.
pub const NO_FALLBACK_MESSAGE: &str = "component(s) have no checker answer and the structural fallback is off";

/// [`ResolverFacts::Off`] for the components the checker did not answer for (`answered` holds the ones it did): each
/// prop's type becomes `opaque` (`unsupportedExpression`), so its `degradedBy` says it has no answer, and one warning
/// per reason (`by_reason`, the backend's fallbacks; a component with none is listed as not answered) names them.
fn without_fallback(output: &mut ExtractionOutput, answered: &[String], mut by_reason: BTreeMap<String, Vec<String>>) {
    let listed: std::collections::BTreeSet<&str> =
        answered.iter().chain(by_reason.values().flatten()).map(String::as_str).collect();
    let silent: Vec<String> = output.components.keys().filter(|key| !listed.contains(key.as_str())).cloned().collect();
    if !silent.is_empty() {
        by_reason.entry("the checker gave no answer for it".to_owned()).or_default().extend(silent);
    }
    for (reason, mut keys) in by_reason {
        keys.sort();
        for key in &keys {
            let Some(entry) = output.components.get_mut(key) else { continue };
            for prop in entry.props.values_mut() {
                let unknown = degraded_type("unknown", OpaqueReason::UnsupportedExpression);
                *prop = Arc::new(ParsedProp::new(
                    prop.name.clone(),
                    unknown,
                    prop.required,
                    None,
                    String::new(),
                    BTreeMap::new(),
                    None,
                    Vec::new(),
                ));
            }
        }
        let mut diagnostic = Diagnostic::new(
            DiagnosticSeverity::Warning,
            DiagnosticCode::SemanticBackend,
            format!("{} {NO_FALLBACK_MESSAGE}: {reason}", keys.len()),
        )
        .with_help("Test-only (--no-resolver-facts): their props are opaque. Without it the structural result stands.");
        diagnostic.affects = keys;
        output.diagnostics.push(diagnostic);
    }
}

