    for (reason, mut keys) in by_reason {
        keys.sort();
        for key in &keys {
            let Some(entry) = output.components.get_mut(key) else { continue };
            for prop in entry.props.values_mut() {
                let unknown = degraded_type("unknown", OpaqueReason::UnsupportedExpression);
                *prop = Arc::new(ParsedProp::new(
                    prop.name.clone(),
                    unknown,
                    prop.required,
                    None,
                    String::new(),
                    BTreeMap::new(),
                    None,
                    Vec::new(),
                ));
            }
        }
        let mut diagnostic = Diagnostic::new(
            DiagnosticSeverity::Warning,
            DiagnosticCode::SemanticBackend,
            format!("{} {NO_FALLBACK_MESSAGE}: {reason}", keys.len()),
        )
        .with_help("Test-only (--no-resolver-facts): their props are opaque. Without it the structural result stands.");
        diagnostic.affects = keys;
        output.diagnostics.push(diagnostic);
    }
}

