/** The component keys each diagnostic whose message passes `test` affects, with that message. */
function affected(output: any, test: (message: string) => boolean): Map<string, string> {
  const keys = new Map<string, string>()
  for (const diagnostic of output.diagnostics ?? []) {
    const message = String(diagnostic.message)
    if (!test(message)) continue
    // `affects` is a list of component keys, or the id of one in `nameLists` (the canonical JSON shares repeated lists).
    const affects = typeof diagnostic.affects === 'string' ? output.nameLists[diagnostic.affects] : diagnostic.affects
    for (const key of affects ?? []) keys.set(key, message)
  }
  return keys
}

/** Each row's component key and prop `p` in one output. */
function propsByRow(output: any): Map<string, { key: string; prop: any }> {
  const byRow = new Map<string, { key: string; prop: any }>()
  for (const [key, component] of Object.entries<any>(output.components)) {
    const id = flattenProps(output, key, component)[PROP]
    for (const row of rowKeysOf(component)) {
      byRow.set(row, { key, prop: id === undefined ? undefined : output.props[id] })
    }
  }
  return byRow
}

/** Run the suite through the checker path, with the structural fallback off and then on, and give every row its
 * verdicts. */
export function runCheckerLane(bin: string): LaneRun {
  const started = performance.now()
  // With the fallback off (ADR 0026, S7b): no fact and no type comes from the structural resolver, and a component the
  // checker did not answer has opaque props, so the lane holds the checker and oxc's syntax alone to every row.
  const checked = extract(bin, ['--no-resolver-facts'])
  const elapsedMs = Math.round(performance.now() - started)
  // The default, with the fallback, as `extract` runs for a user.
  const withFallback = extract(bin, [])

  const backendProblem = [checked, withFallback]
    .flatMap((output) => output.diagnostics ?? [])
    .find((d: any) => String(d.message).includes('checker backend unavailable'))?.message

  /** The component keys the checker answered for, from the provenance diagnostic the merge writes. */
  const answered = affected(checked, (message) => message.includes('resolved by the TypeScript checker'))
  const noAnswer = affected(checked, (message) => message.includes(NO_ANSWER))

  const off = propsByRow(checked)
  const on = propsByRow(withFallback)
  const structural = structuralExpectations().rows
  const rows: Row[] = []
  for (const fixture of listFixtures(suiteDir)) {
    const golden: Golden = JSON.parse(readFileSync(fixture.golden, 'utf8'))
    const key = rowKey(realpathSync(fixture.file), fixture.exportPath)
    const found = off.get(key)
    const foundOn = on.get(key)
    const reason = found && noAnswer.get(found.key)
    rows.push({
      id: fixture.id,
      verdict: rowVerdict(found?.prop, golden),
      structural: structural[fixture.id]?.verdicts ?? [],
      answered: found !== undefined && answered.has(found.key),
      type: found?.prop?.type,
      degradedBy: found?.prop?.degradedBy,
      golden: golden.text,
      facts: factDifferences(found?.prop, golden, suiteDir),
      withFallback: {
        verdict: rowVerdict(foundOn?.prop, golden),
        facts: factDifferences(foundOn?.prop, golden, suiteDir),
      },
      ...(reason && { noAnswer: reason.slice(reason.indexOf(NO_ANSWER) + NO_ANSWER.length) }),
    })
  }
  return { elapsedMs, rows, backendProblem }
}

/** Whether the row reads differently with the structural fallback on than with it off. */
export const dependsOnFallback = (row: Row): boolean =>
  !row.answered ||
  row.withFallback.verdict !== row.verdict ||
  row.withFallback.facts.join() !== row.facts.join()

