/** What is wrong with the run against checker-expectations.json: rows better or worse than allowed with the structural
 * fallback off or on, rows that need the fallback (the checker did not answer, or the answer differs with it on) without
 * a `fallback` entry, a `fallback` entry on a row that reads the same either way, and expectations that do not match
 * the fixtures. Empty when the lane holds. */
export function laneFailures(run: LaneRun, expectations: Expectations): string[] {
  const failures = expectationProblems(
    run.rows.map((row) => row.id),
    expectations.rows,
  )
  for (const row of run.rows) {
    const expectation = expectations.rows[row.id]
    if (expectation === undefined) continue
    const failure = expectationFailure(row.id, row.verdict, expectation)
    if (failure) failures.push(failure)
    failures.push(...factFailures(row.id, row.facts, expectation))
    const { fallback } = expectation
    if (fallback === undefined) {
      if (!row.answered) failures.push(`${row.id}: the checker did not answer for this row (${row.noAnswer ?? 'no reason given'}): list it under "fallback"`)
      else if (dependsOnFallback(row)) failures.push(`${row.id}: the row reads differently with the structural fallback on: list it under "fallback"`)
      continue
    }
    if (!dependsOnFallback(row)) {
      failures.push(`${row.id}: "fallback" is listed, but the row reads the same with the structural fallback off: remove it`)
    }
    const on = `${row.id} (fallback on)`
    const onFailure = expectationFailure(on, row.withFallback.verdict, { verdicts: fallback.verdicts })
    if (onFailure) failures.push(onFailure)
    failures.push(...factFailures(on, row.withFallback.facts, { verdicts: fallback.verdicts, facts: fallback.facts }))
  }
  return failures
}

/** The rows that need the structural fallback, by the cause their `fallback` entry gives (the text before its colon):
 * the worklist of ADR 0026's S7c to S7e. */
export function fallbackWorklist(expectations: Expectations): Map<string, string[]> {
  const worklist = new Map<string, string[]>()
  for (const [id, row] of Object.entries(expectations.rows)) {
    if (row.fallback === undefined) continue
    const cause = row.fallback.cause.slice(0, row.fallback.cause.indexOf(':'))
    worklist.set(cause, [...(worklist.get(cause) ?? []), id])
  }
  return worklist
}

