    const onFailure = expectationFailure(on, row.withFallback.verdict, { verdicts: fallback.verdicts })
    if (onFailure) failures.push(onFailure)
    failures.push(...factFailures(on, row.withFallback.facts, { verdicts: fallback.verdicts, facts: fallback.facts }))
  }
  return failures
}

/** The rows that need the structural fallback, by the cause their `fallback` entry gives (the text before its colon):
 * the worklist of ADR 0026's S7c to S7e. */
export function fallbackWorklist(expectations: Expectations): Map<string, string[]> {
  const worklist = new Map<string, string[]>()
  for (const [id, row] of Object.entries(expectations.rows)) {
    if (row.fallback === undefined) continue
    const cause = row.fallback.cause.slice(0, row.fallback.cause.indexOf(':'))
    worklist.set(cause, [...(worklist.get(cause) ?? []), id])
  }
  return worklist
}

