// Scratch: merge rows into an expectations file, one line per row; existing rows keep their place, a new one goes
// before the first existing id that sorts after it.
// node set-rows.mjs <file> '<json object of id -> entry>'
import { readFileSync, writeFileSync } from 'node:fs'
const [file, patch] = process.argv.slice(2)
const data = JSON.parse(readFileSync(file, 'utf8'))
const entries = Object.entries(data.rows)
for (const [id, entry] of Object.entries(JSON.parse(patch))) {
  const at = entries.findIndex(([existing]) => existing === id)
  if (at >= 0) {
    entries[at][1] = entry
    continue
  }
  const before = entries.findIndex(([existing]) => existing > id)
  entries.splice(before < 0 ? entries.length : before, 0, [id, entry])
}
const lines = entries.map(([id, entry]) => `    ${JSON.stringify(id)}: ${JSON.stringify(entry)}`)
writeFileSync(file, `{\n  "rows": {\n${lines.join(',\n')}\n  }\n}\n`)

